const MediaCard_data = [
    { alt: "a man and a woman are holding hands while sitting on the floor .", imgSrc: "/assets/cloned/images/9072dc460e7c.jpg", style: { backgroundImage: "linear-gradient(var(--clr-0) 0%, var(--clr-81) 100%)" }, title: "Gift of Gratitude", description: "Gratitude is the single most important practice you can add to your life. As Tony says, “When you are grateful, fear disappears and abundance appears.” When you fill your mind with gratitude and thanks, there is no room for negative emotions. You will live in a state of beauty and positivity, bringing light to everyone around you – and the universe will respond in kind.", href: "https://www.tonyrobbins.com/the-gifts-of-life/gratitude/" },
    { alt: "a row of sticky notes with different facial expressions hanging on a clothes line .", imgSrc: "/assets/cloned/images/a690724689db.jpg", style: { backgroundImage: "linear-gradient(var(--clr-0) 0%, var(--clr-82) 100%)" }, title: "Gift of emotion", description: "Emotions make us human. They give life meaning and purpose. They create our most joyful experiences and our more devastating moments. They don’t always feel positive. Yet when we learn to tap into what they are telling us and use them to grow into better versions of ourselves, even emotions like sadness, fear and anger can create positive change.", href: "https://www.tonyrobbins.com/the-gifts-of-life/emotion/" },
    { alt: "a man is getting ready to run on a track .", imgSrc: "/assets/cloned/images/0f339c9d9ab1.jpg", style: { backgroundImage: "linear-gradient(var(--clr-0) 0%, var(--clr-83) 100%)" }, title: "Gift of drive", description: "What does every successful person – from athletes to actors, from doctors to entrepreneurs – have in common? A deep belief in themselves and an insatiable drive to be more, create more, do more and give more. This hunger destroys the fear of failure. It laughs in the face of limitations. It makes you unstoppable. You can learn how to embrace the gift of drive to achieve more than you ever thought possible.", href: "https://www.tonyrobbins.com/the-gifts-of-life/drive/" },
    { alt: "a man and a woman are kissing in a living room .", imgSrc: "/assets/cloned/images/d938b8687936.jpg", style: { backgroundImage: "linear-gradient(var(--clr-0) 0%, var(--clr-84) 100%)" }, title: "Gift of connection", description: "Love and connection are two of the most powerful needs human beings have. They can start wars and end them. They bring us our highest highs and our lowest lows. Without them, life seems empty and cold. But real connection doesn’t just happen. It’s a set of actions we take every day to be present, listen deeply and allow ourselves to be vulnerable. It’s one of the most powerful gifts of life, but it’s also a choice. Will you choose love?", href: "https://www.tonyrobbins.com/the-gifts-of-life/connection/" },
    { alt: "a giraffe and her baby are standing next to each other .", imgSrc: "/assets/cloned/images/6066410edc01.jpg", style: { backgroundImage: "linear-gradient(var(--clr-0) 0%, var(--clr-85) 100%)" }, title: "Gift of consciousness", description: "You’re awake – but are you fully conscious? Do you feel emotions deeply? Do you practice compassion and empathy? Do you live with purpose, confident of your place in the world? When you embrace the gift of consciousness, you open yourself up to a new level of awareness. You connect to your higher self and unlock an ability to surrender that brings true happiness.", href: "https://www.tonyrobbins.com/the-gifts-of-life/consciousness/" },
    { alt: "a small green plant is growing out of a tree stump .", imgSrc: "/assets/cloned/images/52e5fc570e6b.jpg", style: { backgroundImage: "linear-gradient(var(--clr-0) 0%, var(--clr-86) 100%)" }, title: "Gift of growth", description: "If you’re not growing, you’re dying. That’s the plain truth. It’s about more than achieving goals and collecting material wealth. It’s about learning to turn obstacles into opportunities and find the lesson in everything. As Tony says, “No matter how many mistakes you make or how slow you progress, you are still way ahead of everyone who isn’t trying.” Give yourself the gift of growth today.", href: "/the-gifts-of-life" },
    { alt: "a ballerina in a white dress is dancing with a white cloth flying in the air .", imgSrc: "/assets/cloned/images/7dc9451895ee.jpg", style: { backgroundImage: "linear-gradient(var(--clr-0) 0%, var(--clr-87) 100%)" }, title: "Gift of grace", description: "Grace is a guiding force among the gifts of life. It shows up when we need it and when we least expect it. It’s given for no reason at all and it exists with or without you. Some call it luck. Some call it God. You know it when you feel it: It’s a sense of awe and wonder for the small things in life. When you learn to recognize and embrace the gift of grace, you can pass it on to others and change the world.", href: "https://www.tonyrobbins.com/the-gifts-of-life/grace/" },
    { alt: "an elderly couple is riding a bicycle in front of a wooden building .", imgSrc: "/assets/cloned/images/20d716649744.jpg", style: { backgroundImage: "linear-gradient(var(--clr-0) 0%, var(--clr-88) 100%)" }, title: "Gift of presence", description: "We’re not just here to take, we’re here to give. That’s what makes us feel alive. Giving is the ultimate gift of life – and you don’t need money or special skills to do it. The best way to give to others is to be fully present. To give deeply of yourself, your time and attention. The gift of presence, of experiencing every moment fully, is also the greatest gift you can give yourself.", href: "https://www.tonyrobbins.com/the-gifts-of-life/presence/" },
    { alt: "two women are hugging each other in a dark room .", imgSrc: "/assets/cloned/images/56ed6574786b.jpg", style: { backgroundImage: "linear-gradient(var(--clr-0) 0%, var(--clr-89) 100%)" }, title: "Gift of forgiveness", description: "Forgiveness can be one of our greatest challenges in life. It isn’t easy to forgive those who have hurt us, and it can be even harder to forgive ourselves. When you trade your expectations for appreciation, you will realize that forgiveness isn’t a gift you give others – it’s a gift you give yourself. It is freedom from blame and anger and pain. It is the ability to learn from the past, and let it go.", href: "https://www.tonyrobbins.com/the-gifts-of-life/forgiveness/" },
    { alt: "a family is preparing food together in the kitchen .", imgSrc: "/assets/cloned/images/bc7efb3f51d1.jpg", style: { backgroundImage: "linear-gradient(var(--clr-0) 0%, var(--clr-90) 100%)" }, title: "Gift of joy", description: "When you embrace the gifts of life – connection and emotion and gratitude and forgiveness – you will be able to experience pure, genuine joy in life. The type of joy that makes you feel elated, like you’re walking on air. It has nothing to do with what’s happening around you. You can create your own joy, no matter what. It starts right now.", href: "https://www.tonyrobbins.com/the-gifts-of-life/the-gift-of-joy/" }
];
